def note_to_index(note):
    notes = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B']
    return notes.index(note)

def index_to_note(index):
    notes = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B']
    return notes[index]

def transpose(melody, n):
    return [index_to_note((note_to_index(note) + n) % 12) for note in melody]

def invert(melody):
    first_note_index = note_to_index(melody[0])
    return [melody[0]] + [index_to_note((first_note_index - note_to_index(note)) % 12) for note in melody[1:]]

